      ],
      "limitations": [
        "The supplied evidence does not establish improvements under this RecHarness protocol."
      ]
    },
    {
      "title": "TLSTSRec",
      "link": "https://doi.org/10.3233/IDA-240051",
      "contributions": [
        "Models temporal duration and spectrum and adaptively fuses long- and short-term representations."
      ],
      "limitations": [
