      ],
      "limitations": [
        "Does not provide a basis to replace the required pinned evaluator; results must retain their sampled-candidate interpretation."
      ]
    },
    {
      "title": "Statistical Significance Tests for Machine Translation Evaluation",
      "link": "https://aclanthology.org/W04-3250/",
      "contributions": [
        "Provides paired-bootstrap methodology motivating paired per-user recommendation comparisons."
      ],
      "limitations": [
        "The within-category HR bootstrap is an adaptation.",
        "It does not capture training or candidate variability or correct validation selection bias."
      ]
    },
    {
      "title": "On Over-fitting in Model Selection and Subsequent Selection Bias in Performance Evaluation",
      "link": "https://www.jmlr.org/beta/papers/v11/cawley10a.html",
      "contributions": [
        "Explains how repeated model selection can overfit finite validation data and bias reported performance."
      ],
      "limitations": [
        "Reporting search counts and descriptive intervals exposes but does not eliminate selection bias."
      ]
    }
  ]
